// Tailwind CSS fallback implementation
// This is a minimal fallback for basic styling when CDN fails

// Add basic styling classes
document.addEventListener('DOMContentLoaded', function() {
    // Add basic utility classes
    const style = document.createElement('style');
    style.textContent = `
        .container { max-width: 1200px; margin: 0 auto; padding: 0 1rem; }
        .flex { display: flex; }
        .hidden { display: none; }
        .items-center { align-items: center; }
        .justify-between { justify-content: space-between; }
        .text-center { text-align: center; }
        .text-white { color: white; }
        .bg-white { background-color: white; }
        .bg-black { background-color: black; }
        .text-gray-900 { color: #1a202c; }
        .py-3 { padding-top: 0.75rem; padding-bottom: 0.75rem; }
        .px-8 { padding-left: 2rem; padding-right: 2rem; }
        .font-bold { font-weight: 700; }
        .text-xl { font-size: 1.25rem; }
        .uppercase { text-transform: uppercase; }
        .rounded-lg { border-radius: 0.5rem; }
        .shadow-xl { box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04); }
        .transition-colors { transition: background-color 0.2s ease; }
        .hover\\:bg-minecraft:hover { background-color: #54C754; }
        .fixed { position: fixed; }
        .relative { position: relative; }
        .z-50 { z-index: 50; }
        .w-full { width: 100%; }
        .h-screen { height: 100vh; }
        .min-h-screen { min-height: 100vh; }
        .bg-minecraft { background-color: #54C754 !important; }
        .text-minecraft { color: #54C754; }
        .grid { display: grid; }
        .grid-cols-1 { grid-template-columns: repeat(1, minmax(0, 1fr)); }
        .md\\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
        .md\\:grid-cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
        .gap-8 { gap: 2rem; }
        .gap-12 { gap: 3rem; }
        .mb-4 { margin-bottom: 1rem; }
        .mb-6 { margin-bottom: 1.5rem; }
        .mb-8 { margin-bottom: 2rem; }
        .mb-12 { margin-bottom: 3rem; }
        .mt-12 { margin-top: 3rem; }
        .p-6 { padding: 1.5rem; }
        .p-12 { padding: 3rem; }
        .py-4 { padding-top: 1rem; padding-bottom: 1rem; }
        .px-6 { padding-left: 1.5rem; padding-right: 1.5rem; }
        .py-20 { padding-top: 5rem; padding-bottom: 5rem; }
        .text-2xl { font-size: 1.5rem; }
        .text-5xl { font-size: 3rem; }
        .font-medium { font-weight: 500; }
        .font-semibold { font-weight: 600; }
        .rounded-full { border-radius: 9999px; }
        .w-40 { width: 10rem; }
        .h-40 { height: 10rem; }
        .mx-auto { margin-left: auto; margin-right: auto; }
        .text-lg { font-size: 1.125rem; }
        .tracking-widest { letter-spacing: 0.1em; }
        .hover\\:underline:hover { text-decoration: underline; }
        .transition-all { transition: all 0.3s ease; }
        .duration-300 { transition-duration: 300ms; }
        .border-2 { border-width: 2px; }
        .border-white { border-color: white; }
        .hover\\:bg-white:hover { background-color: white; }
        .hover\\:text-gray-900:hover { color: #1a202c; }
        .opacity-0 { opacity: 0; }
        .animate-fade-in { animation: fadeIn 1s ease forwards; }
        @keyframes fadeIn {
            to { opacity: 1; }
        }
    `;
    document.head.appendChild(style);
});